// Juniper's hillside at first light. Scenes stage these drawings; none of them redraws one.
window.W = {
  // A ridge line from a seeded walk: the same hills at every frame and in every scene. at(x) gives its height there.
  ridge(kit, seed, base, amp) {
    const r = kit.rng(seed), ys = [];
    for (let i = 0; i < 15; i++) ys.push(base - amp * r());
    const px = (i) => 160 * i - 160, mid = (i) => (ys[i] + ys[i + 1]) / 2;
    let d = 'M-160 1200 V' + ys[0].toFixed(0);
    for (let i = 1; i < 14; i++) d += ' Q' + px(i) + ' ' + ys[i].toFixed(0) + ' ' + (px(i) + 80) + ' ' + mid(i).toFixed(0);
    return {
      d: d + ' V1200 Z',
      at(x) {
        const i = Math.max(2, Math.min(13, Math.floor((x + 240) / 160))), u = (x - (160 * i - 240)) / 160;
        return (1 - u) * (1 - u) * mid(i - 1) + 2 * u * (1 - u) * ys[i] + u * u * mid(i);
      },
    };
  },
  // Junipers standing on a ridge: narrow and pointed, each its own height, in loose stands. One path for all of them.
  junipers(kit, seed, ridge, n, size) {
    const r = kit.rng(seed);
    let d = '', x = 140 + r() * 200;
    for (let i = 0; i < n; i++) {
      const h = size * (0.55 + r() * 0.7), w = h * 0.3, y = ridge.at(x) + 8;
      d += 'M' + x.toFixed(0) + ' ' + y.toFixed(0) + ' q' + (-w).toFixed(0) + ' ' + (-h * 0.42).toFixed(0) + ' 0 ' + (-h).toFixed(0) + ' q' + w.toFixed(0) + ' ' + (h * 0.58).toFixed(0) + ' 0 ' + h.toFixed(0) + ' Z ';
      x += r() < 0.6 ? 26 + r() * 30 : 150 + r() * 260;
      if (x > 1840) x = 100 + r() * 300;
    }
    return d;
  },
  // Three ridges, far to near, with mist lying between them. Each is its own group, so a scene moves them apart for depth.
  hills(kit, cls) {
    const far = W.ridge(kit, 11, 720, 96), mid = W.ridge(kit, 23, 830, 110), near = W.ridge(kit, 37, 960, 84);
    const mist = (y) => '<rect x="-300" y="' + y + '" width="2520" height="200" fill="url(#' + cls + '-mistfill)"/>';
    return '<defs><linearGradient id="' + cls + '-mistfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--mist);stop-opacity:0"/><stop offset=".55" style="stop-color:var(--mist);stop-opacity:.5"/><stop offset="1" style="stop-color:var(--mist);stop-opacity:0"/></linearGradient></defs>' +
      '<g class="' + cls + '-far"><path d="' + far.d + '" style="fill:var(--hill-far)"/></g><g class="' + cls + '-mist">' + mist(690) + '</g>' +
      '<g class="' + cls + '-mid"><path d="' + W.junipers(kit, 5, mid, 22, 92) + mid.d + '" style="fill:var(--hill-mid)"/></g><g class="' + cls + '-haze">' + mist(820) + '</g>' +
      '<g class="' + cls + '-near"><path d="' + W.junipers(kit, 9, near, 11, 190) + near.d + '" style="fill:var(--hill-near)"/></g>';
  },
  // Steam: each wisp has its own seed, so any frame is worked out from t alone. amount fades all of it in or out.
  steam(kit, n, x, y, rise) {
    const r = kit.rng(n + 3), list = Array.from({ length: n }, () => ({ at: r() * 3.6, x: (r() - 0.5) * 200, sway: 26 + r() * 36, f: 1.1 + r() * 0.9, w: 7 + r() * 9 }));
    return {
      markup: '<g class="steam">' + list.map((p) => '<path style="fill:none;stroke:var(--steam);stroke-linecap:round;stroke-linejoin:round;stroke-width:' + p.w.toFixed(0) + '"/>').join('') + '</g>',
      bind(g) { list.forEach((p, i) => { p.el = g.children[i]; }); },
      render(t, amount) {
        for (const p of list) {
          const q = (((t - p.at) / 3.6) % 1 + 1) % 1, lift = rise * q, len = rise * 0.42, pts = [];
          for (let i = 0; i <= 8; i++) {
            const up = lift + len * i / 8;
            pts.push([x + p.x * (1 - up / rise * 0.4) + p.sway * (up / rise) * Math.sin(up / 64 + t * p.f + p.at * 5), y - up]);
          }
          // Through the midpoints, so the wisp bends and never kinks.
          let d = 'M' + pts[0][0].toFixed(1) + ' ' + pts[0][1].toFixed(1);
          for (let i = 1; i < 8; i++) d += ' Q' + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ' + ((pts[i][0] + pts[i + 1][0]) / 2).toFixed(1) + ' ' + ((pts[i][1] + pts[i + 1][1]) / 2).toFixed(1);
          p.el.setAttribute('d', d);
          p.el.style.opacity = (Math.sin(Math.PI * q) * 0.5 * amount).toFixed(3);
        }
      },
    };
  },
};
